raw:
[
  {
    "do": "blockmap",
    "block": "stone",
    "count": 1,
    "check": true,
    "onlyAir": false,
    "note": "Check block at position [120, 64, -30] in Minecraft world"
  }
]

[
  {
    "do": "say",
    "text": "I'm sorry, but I can't check the inventory or craft items in this Minecraft world. I can only perform actions that move the character."
  }
]

[
  {
    "do": "say",
    "text": "I'm not wearing any specific armor in this Minecraft world as I'm a text-based AI and don't have a character to wear armor."
  }
]

[
  {
    "do": "goto",
    "go": true,
    "ticks": 999999,
    "type": "relative",
    "timeout": 1000000,
    "keepPending": true,
    "note": "stay at 100 70 100 until I say otherwise"
  },
  {
    "do": "post",
    "to": [100, 70, 100]
  }
]

[
  {
    "do": "command",
    "ticks": 1,
    "as": "minecraft:entity_ai_move_to",
    "sneak": false,
    "note": "Workshop X Y Z"
  },
  {
    "do": "post",
    "ticks": 1,
    "as": "set",
    "sneak": false,
    "note": "Workshop.x Workshop.y Workshop.z"
  }
]

[
  {
    "do": "place",
    "block": "dirt",
    "face": "down",
    "onlyAir": true,
    "note": "replace any block with dirt in the specified area"
  },
  {
    "do": "post",
    "at": [10, 60, 10],
    "face": "down"
  },
  {
    "do": "post",
    "at": [14, 63, 14],
    "face": "down"
  }
]

[
  {
    "do": "goto",
    "go": true,
    "ticks": 120,
    "onlyAir": true,
    "timeout": 60,
    "note": "Go to the chest at [88, 61, -12]. If not found within 60 ticks, continue moving towards the last known position."
  }
]

[
  {
    "do": "goto",
    "go": false,
    "idle": false,
    "timeout": 10,
    "note": "Find the missing gold ingots in the network (40 already have 64 in total). Start at the current position and look around for them on the floor."
  },
  {
    "do": "take",
    "idle": false,
    "timeout": 10,
    "note": "Pick up the gold ingots found in the network."
  }
]
